fn main(){let d=std::fs::read("03_infra/fixtures/fonts/UbuntuSans-Variable.ttf").unwrap();let f=rustybuzz::Face::from_slice(&d,0).unwrap();let h=f.glyph_index('H').unwrap().0;let mut r=subsetter::GlyphRemapper::new();let nh=r.remap(h);for w in [250.,900.]{let s=subsetter::subset_with_variations(&d,0,&[(subsetter::Tag::new(b"wght"),w)],&r).unwrap();let f=rustybuzz::Face::from_slice(&s,0).unwrap();println!("wght={w} H={} fvar={}",f.glyph_hor_advance(rustybuzz::ttf_parser::GlyphId(nh)).unwrap(),f.tables().fvar.is_some());}}
